private AlarmTimeSetJsonParse.DayBean convertTimeBarInfoListToDayBean(ArrayList<TimeBarInfo> arrayList) {
    AlarmTimeSetJsonParse.DayBean dayBean = new AlarmTimeSetJsonParse.DayBean();
    ArrayList arrayList2 = new ArrayList();
    dayBean.setSche(arrayList2);
    for (TimeBarInfo timeBarInfo : arrayList) {
        AlarmTimeSetJsonParse.DayBean.ScheBean scheBean = new AlarmTimeSetJsonParse.DayBean.ScheBean();
        scheBean.setS_time(timeBarInfo.getBeginTime().toString("H:m:s"));
        scheBean.setE_time(timeBarInfo.getEndTime().toString("H:m:s"));
        scheBean.setMode(TimeBarInfo.timeBarInfoToDayBeanMode(timeBarInfo.getState()));
        scheBean.setEnable(true);
        arrayList2.add(scheBean);
    }
    dayBean.setCnt(arrayList.size());
    return dayBean;
}
